use vstd::prelude::*;

verus! {

    // Compute the longest character‐sequence in a (possibly empty) vector of sequences.
    // If the input is empty, return None.
    // Otherwise return Some(v) where v is exactly one of the input sequences, v has maximal length,
    // and among all maximal‐length sequences it is the earliest (smallest index).
    fn longest(strings: Vec<Vec<char>>) -> (result: Option<Vec<char>>)
        // If there are no strings, we must return None.
        ensures
            strings.len() == 0 ==> result.is_None(),
        // If there is at least one string, we must return Some(seq) with the required properties.
        ensures
            strings.len() > 0 ==>
                result.is_Some() &&
                (exists |i: usize|
                    i < strings.len() &&
                    // We return exactly the i‐th input sequence (by content).
                    result.get_Some_0() == strings[i] &&
                    // Its length is ≥ the length of every input.
                    forall |j: usize| j < strings.len() ==> strings[j].len() <= strings[i].len() &&
                    // For every j < i, the j‐th string is strictly shorter.
                    forall |j: usize| j < i            ==> strings[j].len() <  strings[i].len()
                )
    {
        let n = strings.len();
        if n == 0 {
            return None;
        }
        // We know n ≥ 1 here.
        let mut best_idx: usize = 0;
        let mut i: usize = 1;
        // Invariants:
        //   1 ≤ i ≤ n
        //   best_idx < i
        //   for all j < i: strings[best_idx].len() ≥ strings[j].len()
        //   for all j < best_idx: strings[j].len() < strings[best_idx].len()
        while i < n
            invariant 1 <= i && i <= n,
            invariant best_idx < i,
            invariant forall |j: usize| j < i             ==> strings[best_idx].len() >= strings[j].len(),
            invariant forall |j: usize| j < best_idx      ==> strings[j].len()             < strings[best_idx].len(),
            decreases n - i,
        {
            if strings[i].len() > strings[best_idx].len() {
                best_idx = i;
            }
            i += 1;
        }
        // At this point i == n, and best_idx < n, and the invariants guarantee:
        //   * strings[best_idx] is one of the inputs,
        //   * it has maximal length ≥ all others,
        //   * for all j < best_idx, strings[j] is strictly shorter.

        // Return a clone of the best sequence.
        let res: Vec<char> = strings[best_idx].clone();
        // Clone preserves content equality.
        assert(res == strings[best_idx]);
        Some(res)
    }
}

